const words={"pt-BR":["Sua jornada no poker começa aqui.","ENTRAR COM GOOGLE","ENTRAR COM BIOMETRIA","ENTRAR COM STACKUP ID","EXPLORAR PRÉVIA","E-mail","Senha","ENTRAR","VOLTAR","Autenticação ainda não conectada. Este front está pronto para receber o serviço do app."],"en-US":["Your poker journey starts here.","SIGN IN WITH GOOGLE","SIGN IN WITH BIOMETRICS","SIGN IN WITH STACKUP ID","EXPLORE PREVIEW","Email","Password","SIGN IN","BACK","Authentication is not connected yet. This frontend is ready for the app service."],"es-ES":["Tu aventura en el póker comienza aquí.","ENTRAR con Google","ENTRAR con Biometría","ENTRAR con StackUp ID","EXPLORAR VISTA PREVIA","Correo electrónico","Contraseña","ENTRAR","VOLVER","La autenticación aún no está conectada. Este front está listo para recibir el servicio de la app."]};
let lang='pt-BR',showId=false,register=false,busy=false;try{lang=localStorage.getItem('stackup.locale')||lang}catch{}if(!words[lang])lang='pt-BR';
export function loginPage(app,product){document.documentElement.lang=lang;document.body.classList.add('login-screen');const w=words[lang];app.innerHTML=`<section class="entry"><div class="entry-art"><img src="assets/${product==='HEROES'?'pokerino-heroes':'pokerino-hero'}.webp" alt="POKERINNO"><div class="pokerinno-logo" role="img" aria-label="POKERINNO ACADEMY"><svg viewBox="0 0 32 38" aria-hidden="true"><path d="M16 1C12 8 1 13 1 23c0 7 8 10 13 5l-3 9h10l-3-9c5 5 13 2 13-5C31 13 20 8 16 1Z"/></svg><div><strong>POKERINNO</strong><span>ACADEMY</span></div></div></div><div class="entry-form">${showId?`<div class="page-actions"><button type="button" class="back app-back" data-entry-back>${w[8]}</button></div>`:''}<h2>${w[0]}</h2><div class="entry-languages" aria-label="Idioma">${[['pt-BR','PT BR'],['en-US','EN US'],['es-ES','ES ES']].map(([v,t])=>`<button data-locale="${v}" aria-pressed="${lang===v}">${t}</button>`).join('')}</div>${showId?`<form id="stackup-login">${register?`<label>${lang==='pt-BR'?'Nome':lang==='en-US'?'Name':'Nombre'}<input name="displayName" autocomplete="name" required></label>`:''}<label>${w[5]}<input name="email" type="email" autocomplete="username" required></label><label>${w[6]}<input name="password" type="password" autocomplete="current-password" required minlength="6"></label><button class="primary" type="submit">${register?(lang==='pt-BR'?'CRIAR CONTA STACKUP':lang==='en-US'?'CREATE STACKUP ACCOUNT':'CREAR CUENTA STACKUP'):w[7]}</button></form>`:`<div class="entry-buttons"><button data-auth="google"><span class="entry-auth-icon entry-auth-google" aria-hidden="true"><img src="assets/google-g-official.png" width="20" height="20" alt=""></span>${w[1]}</button><button data-auth="biometric"><span class="entry-auth-icon entry-auth-biometric" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7a9 9 0 0 1 16 0M2 12a10 10 0 0 1 .4-2.8M22 12a10 10 0 0 0-.4-2.8M5 12a7 7 0 0 1 14 0c0 2.1.2 4.2.9 6.2M5 15c0 2-.3 4-1 5.8M8 13v-1a4 4 0 0 1 8 0c0 3.7.4 6.5 1.5 9M8 16c0 2.1-.3 4.1-1 6M11 21c.7-2.8 1-6 1-9M14 17c.2 1.7.6 3.4 1.2 5"/></svg></span>${w[2]}</button><button data-auth="stackup"><span class="entry-auth-icon entry-auth-stackup" aria-hidden="true"><img src="assets/stackup-logo-transparent.png" width="32" height="32" alt=""></span>${w[3]}</button></div>`}<button class="quiet" data-create-account>${lang==='pt-BR'?'CRIAR CONTA STACKUP':lang==='en-US'?'CREATE STACKUP ACCOUNT':'CREAR CUENTA STACKUP'}</button><p id="entry-status" role="status"></p><a class="quiet" href="#home">${w[4]} →</a></div></section>`;app.querySelectorAll('[data-locale]').forEach(b=>b.onclick=()=>{lang=b.dataset.locale;try{localStorage.setItem('stackup.locale',lang)}catch{}loginPage(app,product)});app.querySelector('[data-entry-back]')?.addEventListener('click',()=>{showId=false;register=false;loginPage(app,product)});app.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{if(b.dataset.auth==='stackup'){showId=true;register=false;loginPage(app,product)}else authenticate(b.dataset.auth,{},app)});app.querySelector('[data-create-account]').onclick=()=>{showId=true;register=true;loginPage(app,product)};app.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;authenticate(register?'register':'stackup',{email:f.email.value,password:f.password.value,...(register?{name:f.displayName.value}:{})},app)});}
async function authenticate(method,payload,app){if(busy)return;const adapter=window.StackUpAuthAdapter,status=app.querySelector('#entry-status');const operation=method==='register'?adapter?.signUp:adapter?.signIn;if(typeof operation!=='function'){status.textContent=words[lang][9];return}busy=true;app.querySelectorAll('button').forEach(b=>b.disabled=true);try{const result=await operation.call(adapter,{method,locale:lang,...payload});if(result?.authenticated===true)location.hash='home';else status.textContent=words[lang][9]}catch{status.textContent=words[lang][9]}finally{busy=false;app.querySelectorAll('button').forEach(b=>b.disabled=false)}}
